// WS-04 Phase 2/3 milestone: observe OCR/extraction completion and
// failure, and surface documents that need escalation. This is a
// read-only sequencing/observability check -- it does not retry or
// mutate any document. There is currently no supported transition back
// out of 'failed'/'complete' (see Progress.md Technical Debt), so a
// blind automatic retry here would just be a silent no-op against the
// internal API; escalation is logged for a human/WS-06 to act on instead.
const STALE_THRESHOLD_MS = 15 * 60 * 1000;
const now = Date.now();
const escalations = [];

for (const item of $input.all()) {
  const doc = item.json;
  const updatedAtMs = new Date(doc.updatedAt).getTime();
  const isFailed = doc.status === 'failed';
  const isStuck = (doc.status === 'queued' || doc.status === 'processing') && (now - updatedAtMs) > STALE_THRESHOLD_MS;

  if (isFailed || isStuck) {
    escalations.push({
      json: {
        documentId: doc.id,
        status: doc.status,
        errorMessage: doc.errorMessage || null,
        reason: isFailed ? 'failed' : 'stuck_in_processing',
        updatedAt: doc.updatedAt,
      },
    });
  }
}

return escalations;
